import{annotate}from"./rough-notation.js";function annotateOnFocus(t,e){for(const o of["mouseover","focus"])t.addEventListener(o,(()=>{e.show()}));for(const o of["mouseout","blur"])t.addEventListener(o,(()=>{e.hide()}))}const links=document.querySelectorAll("a"),linkAnnotateArray=[];links.forEach(((t,e)=>{linkAnnotateArray.push(annotate(t,{type:"highlight",color:"rgba(253, 166, 166, 0.3)",padding:15})),annotateOnFocus(t,linkAnnotateArray[e])}));const pictures=document.querySelectorAll(".img-box"),captionAnnotateArray=[];pictures.forEach(((t,e)=>{const o=t.querySelector(".caption");window.matchMedia("(prefers-color-scheme: dark)").matches?captionAnnotateArray.push(annotate(o,{type:"bracket",color:"#fff",strokeWidth:4,padding:[10,10],brackets:["left","right"]})):captionAnnotateArray.push(annotate(o,{type:"bracket",color:"#000",strokeWidth:4,padding:[10,10],brackets:["left","right"]})),annotateOnFocus(t,captionAnnotateArray[e])})),document.onkeydown=function(t){"Escape"===t.key&&document.querySelector(".modal-toggle:checked ~ .modal .modal-close")&&document.querySelector(".modal-toggle:checked ~ .modal .modal-close").click()};const fontSwitcher=document.getElementById("font-switcher");fontSwitcher.addEventListener("click",(()=>{fontSwitcher.toggleAttribute("checked")?(document.body.style.fontFamily="IBM Plex Sans Thai",document.body.style.fontSize="1.15rem"):(document.body.style.fontFamily="Reenie Beanie",document.body.style.fontSize="1.75rem")}));